fn bluetoothState(&self) -> HostResult<BluetoothStateData> {
    let radios = enumerate_radios();
    Ok(BluetoothStateData {
        supported: !radios.is_empty(),
        enabled: !radios.is_empty(),
        state: if radios.is_empty() {
            "unavailable"
        } else {
            "enabled"
        }

pub fn defaultRuntimeRoot() -> PathBuf {
    let appdata =
        env::var_os("APPDATA").expect("APPDATA is required for Operit2 runtime storage");
    PathBuf::from(appdata).join("Operit2").join("runtime")
